function FastAgentIcon(props: { size: number, class?: string }): JSX.Element {
  // Fast Agent's own mark (docs/docs/assets/brand/fast-agent-icon.svg): the
  // amber bolt on the project's dark tile, verbatim.
  return (
    <svg
      height={props.size}
      width={props.size}
      viewBox="0 0 256 256"
      xmlns="http://www.w3.org/2000/svg"
      class={props.class}
      style={iconStyle(props.size)}
    >
      <rect width="256" height="256" rx="32" fill="#10151f" />
      <path d="M94.340 208L131.300 208L161 128.140L131.300 47.400L94.340 47.400L124.040 127.700L94.340 208Z" fill="#f5a400" />
    </svg>
  )
}

export interface AgentProviderIconProps {
  provider?: AgentProvider
  size: number
  class?: string
}

export function AgentProviderIcon(props: AgentProviderIconProps): JSX.Element {
  // Conditional spread so an absent `class` stays absent: these prop types
  // treat a present-but-undefined class differently under
  // exactOptionalPropertyTypes, and lucide's own props are not ours to widen.
  const classProps = () => (props.class !== undefined ? { class: props.class } : {})
  return (
    <Switch fallback={<Bot size={props.size} {...classProps()} style={iconStyle(props.size)} />}>
      <Match when={props.provider === AgentProvider.CLAUDE_CODE}>
        <ClaudeCodeIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.CODEX}>
        <CodexIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.OPENCODE}>
        <OpenCodeIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.GITHUB_COPILOT}>
        <GitHubCopilotIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.CURSOR}>
        <CursorIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.GOOSE}>
        <GooseIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.KILO}>
        <KiloIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.PI}>
        <PiIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.REASONIX}>
        <ReasonixIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.ZCODE}>
        <ZCodeIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.CODEWHALE}>
        <CodewhaleIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.KIMI_CODE}>
        <KimiCodeIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.MIMO_CODE}>
        <MiMoCodeIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.QWEN_CODE}>
        <QwenCodeIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.OH_MY_PI}>
        <OhMyPiIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.GROK_BUILD}>
        <GrokBuildIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.KIRO}>
        <KiroIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.AMP}>
        <AmpIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.CLINE}>
        <ClineIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.CODEBUDDY}>
        <CodeBuddyIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.JUNIE}>
        <JunieIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.LETTA}>
        <LettaIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.DIRAC}>
        <DiracIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.QODER}>
        <QoderIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.DROID}>
        <DroidIcon size={props.size} {...classProps()} />
      </Match>
      <Match when={props.provider === AgentProvider.FAST_AGENT}>
        <FastAgentIcon size={props.size} {...classProps()} />
      </Match>
    </Switch>
  )
}
